style.css:
/* 
   Hacker Terminal Style 2026
   Target: Global (All Websites)
*/

/* 1. Global Terminal Aesthetics */
* {
    background-color: #000000 !important;
    color: #00FF41 !important; /* Matrix/Terminal Green */
    font-family: "Courier New", Courier, monospace !important;
    border-color: #008F11 !important;
    text-shadow: 0 0 5px #00FF41 !important;
}

/* Link Styling */
a {
    color: #00FF41 !important;
    text-decoration: underline !important;
}

/* 2. Loading Screen Overlay */
/* This creates a black screen for 5 seconds every time a new page/link is opened */
body::before {
    content: "LOADING";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: #000000 !important;
    color: #00FF41 !important;
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 3rem;
    font-weight: bold;
    z-index: 999999;
    pointer-events: all;
    
    /* Animations: Dots cycle every 1.5s, screen disappears after 5s */
    animation: 
        loadingDots 1.5s infinite steps(4), 
        hideOverlay 0s forwards 5s;
}

/* Three dots animation (...) */
@keyframes loadingDots {
    0%   { content: "LOADING"; }
    25%  { content: "LOADING."; }
    50%  { content: "LOADING.."; }
    75%  { content: "LOADING..."; }
    100% { content: "LOADING"; }
}

/* Hides the loading screen exactly after 5 seconds */
@keyframes hideOverlay {
    to {
        visibility: hidden;
        opacity: 0;
        pointer-events: none;
        display: none;
    }
}

/* Optional: CRT Scanline effect for extra "hacker" vibe */
body::after {
    content: " ";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), 
                linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06));
    background-size: 100% 4px, 3px 100%;
    z-index: 999998;
    pointer-events: none;
}
